CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, name text, avatar_url text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE workspaces (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, owner_id uuid NOT NULL REFERENCES users(id), plan text NOT NULL DEFAULT 'free', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE workspace_members (workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, role text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(workspace_id,user_id));
CREATE TABLE locations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, name text NOT NULL, address text, country text, timezone text NOT NULL, source text NOT NULL, external_id text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(source,external_id));
CREATE INDEX locations_workspace_idx ON locations(workspace_id);

CREATE TABLE integrations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, provider text NOT NULL, status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,provider));
CREATE TABLE oauth_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), integration_id uuid NOT NULL REFERENCES integrations(id) ON DELETE CASCADE, external_account_id text NOT NULL, access_token_ciphertext bytea NOT NULL, refresh_token_ciphertext bytea NOT NULL, encryption_key_id text NOT NULL, expires_at timestamptz, scopes text[] NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(integration_id,external_account_id));

CREATE TABLE reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, location_id uuid NOT NULL REFERENCES locations(id) ON DELETE CASCADE, provider text NOT NULL, external_id text NOT NULL, rating smallint NOT NULL CHECK(rating BETWEEN 1 AND 5), text text, author_name text, created_at_external timestamptz NOT NULL, updated_at_external timestamptz, reply_text text, reply_created_at timestamptz, language text, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(location_id,provider,external_id));
CREATE INDEX reviews_location_created_idx ON reviews(location_id,created_at_external DESC);
CREATE INDEX reviews_expiry_idx ON reviews(expires_at) WHERE text IS NOT NULL OR author_name IS NOT NULL OR reply_text IS NOT NULL;

CREATE TABLE review_analysis (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), review_id uuid NOT NULL UNIQUE REFERENCES reviews(id) ON DELETE CASCADE, sentiment text NOT NULL, sentiment_score numeric(5,4) NOT NULL CHECK(sentiment_score BETWEEN -1 AND 1), emotion text, urgency text NOT NULL, summary text NOT NULL, language text NOT NULL, actionable boolean NOT NULL DEFAULT false, model_version text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE topics (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, name text NOT NULL, slug text NOT NULL, origin text NOT NULL, UNIQUE(workspace_id,slug));
CREATE TABLE review_topics (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), review_id uuid NOT NULL REFERENCES reviews(id) ON DELETE CASCADE, topic_id uuid NOT NULL REFERENCES topics(id), sentiment text NOT NULL, confidence numeric(5,4) NOT NULL CHECK(confidence BETWEEN 0 AND 1), UNIQUE(review_id,topic_id));
CREATE INDEX review_topics_topic_idx ON review_topics(topic_id,review_id);

CREATE TABLE insights (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, topic_id uuid REFERENCES topics(id), kind text NOT NULL, severity text, current_count integer NOT NULL, previous_count integer NOT NULL, growth_percent numeric(8,2), explanation text, recommended_action text, period_start timestamptz NOT NULL, period_end timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE alerts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, event_type text NOT NULL, threshold numeric, channels text[] NOT NULL, enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE alert_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), alert_id uuid NOT NULL REFERENCES alerts(id) ON DELETE CASCADE, event_key text NOT NULL, payload jsonb NOT NULL, status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), sent_at timestamptz, UNIQUE(alert_id,event_key));
CREATE TABLE reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, period_start timestamptz NOT NULL, period_end timestamptz NOT NULL, payload jsonb NOT NULL, reputation_score numeric(5,2), formula_version text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,period_start,period_end));
CREATE TABLE subscriptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL UNIQUE REFERENCES workspaces(id) ON DELETE CASCADE, plan text NOT NULL, status text NOT NULL, provider_customer_id text, provider_subscription_id text, current_period_end timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), provider_payment_id text NOT NULL UNIQUE, amount_cents integer NOT NULL, currency char(3) NOT NULL, status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
